onChange={e => {
  const current = settings.streamEndpoints ?? DEFAULT_ENDPOINT_PATHS
  const next = e.target.checked
    ? [...current, path]
    : current.filter(ep => ep !== path)
  setSettings(s => s ? { ...s, streamEndpoints: next as CHStreamEndpoint[] } : s)
}}

new_string:
onChange={e => {
  const current = settings.streamEndpoints ?? DEFAULT_ENDPOINT_PATHS
  const next = (e.target.checked
    ? [...current, path]
    : current.filter(ep => ep !== path)) as CHStreamEndpoint[]
  // Saved at once, and the stream follows the new choice.
  void window.api.setStreamEndpoints(next).then((r) => {
    if (r.success) setSettings(s => s ? { ...s, streamEndpoints: next } : s)
    else tell(false, (r as { error?: string }).error || 'The streams couldn’t be changed.')
  })
}}
